    String textoIngresado, textoMostrado, letraIngresada;
    String[] matrizTexto;
    int intentos, fallos, aciertos, longi;
    
    private void biniciarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_biniciarActionPerformed
        // TODO add your handling code here:
        intentos=0;
        fallos=0;
        aciertos=0;
        textoMostrado="";
        textoIngresado=ppalabra.getText().toLowerCase();
        longi =textoIngresado.length();
        matrizTexto=new String[longi];
        for (int i = 0; i < longi; i++) {
            matrizTexto[i]="-";
            textoMostrado+=matrizTexto[i]+" ";
        }
        tintentos.setText(String.valueOf(intentos));
        tfallos.setText(String.valueOf(fallos));
        taciertos.setText(String.valueOf(aciertos));
        tletra.setText("");
        tguion.setText(textoMostrado);
        t1.setBackground(Color.WHITE);
        t2.setBackground(Color.WHITE);
        t3.setBackground(Color.WHITE);
        t4.setBackground(Color.WHITE);
        t5.setBackground(Color.WHITE);
    }//GEN-LAST:event_biniciarActionPerformed

    private void baceptarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_baceptarActionPerformed
        // TODO add your handling code here:
        String palabra="";
        char letra;
        boolean resp=false;
        letraIngresada=tletra.getText();
        letra=Character.toLowerCase(letraIngresada.charAt(0));
        intentos++;
        textoMostrado="";
        for (int i = 0; i < longi; i++) {
            if (textoIngresado.charAt(i)==letra) {
                matrizTexto[i]=String.valueOf(letra);
                resp=true;
            }
            textoMostrado+=matrizTexto[i]+" ";
        }
        if (resp==true) {
            aciertos++;
        }else{
            fallos++;
        }
        for (int i = 0; i < longi; i++) {
            palabra+=matrizTexto[i];
        }
        if (palabra.equals(textoIngresado)) {
            JOptionPane.showMessageDialog(null, "GANASTE");
        }
        switch (fallos) {
            case 0:
                break;
            case 1:
                t1.setBackground(Color.cyan);
                break;
            case 2:
                t2.setBackground(Color.green);
                break;
            case 3:
                t3.setBackground(Color.YELLOW);
                break;
            case 4:
                t4.setBackground(Color.ORANGE);
                break;
            default:
                t5.setBackground(Color.RED);
                JOptionPane.showMessageDialog(null, "PERDISTE\nla palabra es: "+textoIngresado);
                textoMostrado=textoIngresado;
                break;
        }
        tletra.setText("");
        tintentos.setText(String.valueOf(intentos));
        tfallos.setText(String.valueOf(fallos));
        taciertos.setText(String.valueOf(aciertos));        
        tguion.setText(textoMostrado);
    }//GEN-LAST:event_baceptarActionPerformed

